export { anatomy, parts, type ToastPart } from "./toast.anatomy";
export { connect } from "./toast.connect";
export {
  getDescriptionId,
  getGroupEl,
  getGroupId,
  getRootId,
  getTitleId,
  getToastEl,
  getToastEls,
} from "./toast.dom";
export { machine } from "./toast.machine";
export { createToaster } from "./toast.store";
export type {
  ResolvedToastGroupMachineProps,
  ToastActionOptions,
  ToastApi,
  ToastDismissDetails,
  ToastDismissReason,
  Toaster,
  ToasterOptions,
  ToastGroupMachineProps,
  ToastGroupSchema,
  ToastOptions,
  ToastPlacement,
  ToastPromiseOptions,
  ToastRecord,
  ToastStatus,
  ToastSubscriber,
  ToastTranslations,
  ToastType,
} from "./toast.types";

import { ariaAttr, dataAttr } from "../../dom/attrs";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./toast.anatomy";
import { getDescriptionId, getGroupId, getRootId, getTitleId } from "./toast.dom";
import type { ToastApi, ToastGroupSchema, ToastRecord } from "./toast.types";

export function connect<T extends PropTypes>(
  service: Service<ToastGroupSchema>,
  normalize: NormalizeProps<T>,
): ToastApi<T> {
  const { context, prop, computed, send, scope } = service;

  const toaster = prop("toaster");
  const toasts = context.get("toasts");
  const paused = context.get("pausedByInteraction");
  const translations = prop("translations");
  const count = computed("visibleCount");
  const frontId = computed("frontId");

  // The two defaults live here rather than in the machine's `props`: a machine's
  // resolved props are also its *input* type, so promoting these to required
  // would make an adapter that passes only one of the two fail to typecheck.
  const regionLabel = translations.regionLabel?.(count) ?? `Notifications (${count})`;
  const dismissLabel = translations.dismissLabel ?? "Dismiss notification";

  const indexOf = (toast: ToastRecord): number =>
    toasts.findIndex((record) => record.id === toast.id);

  /**
   * Arrows, Home and End come from the shared roving arithmetic — the same
   * function the composites use, so a d-pad and a keyboard cannot disagree about
   * what `next` means. Escape is answered here rather than by a dismissable layer
   * because the toasts are not on the layer stack: a global Escape belongs to
   * whatever menu or dialog is really open.
   */
  const onRegionKeyDown = (event: KeyboardEvent, id: string | null): void => {
    if (event.defaultPrevented) return;
    const action = getRovingKeyAction(event.key);
    if (action !== null) {
      event.preventDefault();
      send({ type: "TOAST.NAVIGATE", to: action });
      return;
    }
    if (event.key !== "Escape" || id === null) return;
    event.preventDefault();
    send({ type: "TOAST.DISMISS", id, reason: "escape" });
  };

  return {
    toasts,
    count,
    queuedCount: toaster.getQueuedCount(),
    paused,

    focusGroup(): void {
      send({ type: "GROUP.HOTKEY" });
    },

    dismiss(id?: string | undefined): void {
      send({ type: "TOAST.DISMISS", id, reason: "programmatic" });
    },

    notifyExit(id: string): void {
      send({ type: "TOAST.EXITED", id });
    },

    getGroupProps: (): T["element"] =>
      normalize.element({
        ...parts.group.attrs,
        id: getGroupId(scope),
        role: "region",
        "aria-label": regionLabel,
        // Focusable but not tabbable: the hotkey and `api.focusGroup()` put the
        // focus here, and nothing else may.
        tabIndex: -1,
        dir: prop("dir"),
        "data-placement": toaster.placement,
        "data-overlap": dataAttr(toaster.overlap),
        "data-paused": dataAttr(paused),
        "data-expanded": dataAttr(paused),
        // Spatial navigation never routes into a notification region on its own
        // (components.md T2): arriving here is always something the person did.
        "data-snav-ignore": "",
        style: { "--sui-toast-count": String(count) },
        onPointerEnter() {
          send({ type: "GROUP.POINTER_ENTER" });
        },
        onPointerLeave() {
          send({ type: "GROUP.POINTER_LEAVE" });
        },
        onFocusIn(event) {
          send({ type: "GROUP.FOCUS_ENTER", relatedTarget: event.relatedTarget });
        },
        onFocusOut(event) {
          send({ type: "GROUP.FOCUS_LEAVE", relatedTarget: event.relatedTarget });
        },
        onKeyDown(event) {
          onRegionKeyDown(event, frontId);
        },
      }),

    /**
     * `role` for navigability, `aria-live="off"` so the card does not read itself
     * — the speech goes through the document's shared announcer (spec §0.4, the
     * Radix pattern). A title is required on every record, so `aria-labelledby`
     * is unconditional; the description is only pointed at when the record has
     * one, because a dangling IDREF names nothing.
     */
    getRootProps: (toast: ToastRecord): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope, toast.id),
        role: toast.politeness === "assertive" ? "alert" : "status",
        "aria-live": "off",
        "aria-atomic": ariaAttr(true),
        "aria-labelledby": getTitleId(scope, toast.id),
        "aria-describedby":
          toast.description === undefined ? undefined : getDescriptionId(scope, toast.id),
        // Every card is its own tab stop. A stack capped at three does not earn a
        // roving composite, and a toast can leave under the focus at any moment —
        // which is what the hand-off exists for, not a single tab stop.
        tabIndex: 0,
        "data-type": toast.type,
        "data-state": toast.status === "visible" ? "open" : "closed",
        "data-front": dataAttr(toast.id === frontId),
        "data-paused": dataAttr(paused),
        "data-placement": toaster.placement,
        // The card applies the material, so it is the card that has to say so:
        // nothing inside it can find out what is painted behind it.
        "data-sui-on-glass": "",
        style: { "--sui-toast-index": String(indexOf(toast)) },
        onKeyDown(event) {
          onRegionKeyDown(event, toast.id);
        },
      }),

    getIndicatorProps: (toast: ToastRecord): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        "aria-hidden": ariaAttr(true),
        "data-type": toast.type,
      }),

    getTitleProps: (toast: ToastRecord): T["element"] =>
      normalize.element({ ...parts.title.attrs, id: getTitleId(scope, toast.id) }),

    getDescriptionProps: (toast: ToastRecord): T["element"] =>
      normalize.element({ ...parts.description.attrs, id: getDescriptionId(scope, toast.id) }),

    getActionTriggerProps: (toast: ToastRecord): T["button"] =>
      normalize.button({
        ...parts.actionTrigger.attrs,
        type: "button",
        "data-type": toast.type,
        onClick(event) {
          if (event.defaultPrevented) return;
          const action = toast.action;
          if (action === undefined) return;
          action.onClick();
          if (action.dismissOnClick === false) return;
          send({ type: "TOAST.DISMISS", id: toast.id, reason: "action" });
        },
      }),

    getCloseTriggerProps: (toast: ToastRecord): T["button"] =>
      normalize.button({
        ...parts.closeTrigger.attrs,
        type: "button",
        "aria-label": dismissLabel,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "TOAST.DISMISS", id: toast.id, reason: "close-trigger" });
        },
      }),
  };
}

import { queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "toast";

export function getGroupId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "group");
}

/** `toast:{scope}:root:{toast id}` — the repeating part keyed by the record's own id. */
export function getRootId(scope: Scope, id: string): string {
  return getPartId(scope, COMPONENT, "root", id);
}

export function getTitleId(scope: Scope, id: string): string {
  return getPartId(scope, COMPONENT, "title", id);
}

export function getDescriptionId(scope: Scope, id: string): string {
  return getPartId(scope, COMPONENT, "description", id);
}

export function getGroupEl(scope: Scope): HTMLElement | null {
  return scope.getById(getGroupId(scope));
}

export function getToastEl(scope: Scope, id: string): HTMLElement | null {
  return scope.getById(getRootId(scope, id));
}

/** The stack index `connect` writes on every card; its position, for a node without one. */
function readIndex(node: HTMLElement, fallback: number): number {
  const raw = Number.parseInt(node.style.getPropertyValue("--sui-toast-index"), 10);
  return Number.isNaN(raw) ? fallback : raw;
}

/**
 * Front first, which is the context's order — ordered by the `--sui-toast-index`
 * `connect` writes on each card rather than by sibling order. Document order used
 * to *be* the claim, and it is one no adapter is forced to honour: the store is
 * newest-first, so an adapter that appends each arrival to the end of the region
 * paints the stack back to front, and nothing in the DOM says so. The measured
 * offsets and the focus walk would both come out silently inverted. Sorting here
 * costs one pass over a list capped at `max`.
 */
export function getToastEls(scope: Scope): HTMLElement[] {
  return queryAll<HTMLElement>(getGroupEl(scope), '[data-part~="toast:root"]')
    .map((node, position) => ({ node, position, index: readIndex(node, position) }))
    .sort((a, b) => a.index - b.index || a.position - b.position)
    .map((entry) => entry.node);
}

/**
 * The group: the store's bridge to a page, and the three decisions that shape it.
 *
 * **Nothing ever steals the focus.** No `focus()` on arrival, whatever the
 * severity — a notification that yanks the caret out of an input is a bug the
 * severity does not excuse. The only ways in are the hotkey, `api.focusGroup()`
 * and a plain Tab; the only focus write the library performs is the hand-off when
 * the toast a person is standing on leaves under them.
 *
 * **Toasts are not a dismissable layer.** They never touch the layer stack, so a
 * global Escape or a gamepad B keeps dismissing the menus and dialogs above them
 * as if the region were not there. Both act on a toast only once the DOM focus is
 * already inside the region.
 *
 * **The role is on the card, the speech is the announcer's.** The root carries
 * `role="status"` or `role="alert"` so a screen reader can navigate to it, and
 * `aria-live="off"` so it does not also read itself — the text goes through the
 * document's shared live region, which is created empty and up front and is
 * therefore the only one that reliably speaks.
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { addDomEvent } from "../../dom/event";
import { observeChildren } from "../../dom/observers";
import { contains, isHTMLElement } from "../../dom/query";
import { getNextIndex, getRemovalIndex } from "../../focus/roving-focus";
import { trackScrollEdges } from "../../interaction/scroll-edges";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement } from "../../nav";
import { invariant } from "../../utils/invariant";
import { getGroupEl, getToastEl, getToastEls } from "./toast.dom";
import type { ResolvedToastGroupMachineProps, ToastGroupSchema, ToastRecord } from "./toast.types";

type Params = MachineParams<ToastGroupSchema>;

const DEFAULT_HOTKEY: readonly string[] = ["F6"];
const DEFAULT_GAP = 8;

/** One hold, shared by the pointer and the focus: two acquisitions, two releases. */
const INTERACTION = "interaction";
const PAGE_IDLE = "page-hidden";

const MODIFIERS: Readonly<Record<string, (event: KeyboardEvent) => boolean>> = {
  altKey: (event) => event.altKey,
  ctrlKey: (event) => event.ctrlKey,
  metaKey: (event) => event.metaKey,
  shiftKey: (event) => event.shiftKey,
};

/**
 * Every entry has to match. A modifier is named by its flag; anything else is
 * compared against `event.code` first — `KeyT` survives a Dvorak layout — and
 * then against `event.key`, which is what `"F6"` and `"Escape"` answer to.
 */
export function matchesHotkey(event: KeyboardEvent, hotkey: readonly string[]): boolean {
  if (hotkey.length === 0) return false;
  return hotkey.every((entry) => {
    const modifier = MODIFIERS[entry];
    if (modifier !== undefined) return modifier(event);
    return event.code === entry || event.key === entry;
  });
}

/**
 * By the record's own id, never by a position in a DOM walk: the index this
 * returns is read straight back out of `toasts`, so a walk whose order an adapter
 * had inverted would answer with a different record than the one under the focus.
 */
function focusedIndex(params: Params): number {
  const { scope, context } = params;
  const active = scope.getActiveElement();
  if (active === null) return -1;
  return context
    .get("toasts")
    .findIndex((record) => contains(getToastEl(scope, record.id), active));
}

function focusedToast(params: Params): ToastRecord | undefined {
  const index = focusedIndex(params);
  return index === -1 ? undefined : params.context.get("toasts")[index];
}

/**
 * The APG hand-off, and the whole reason `getRemovalIndex` is shared with the
 * roving composites: when the toast under the focus leaves, the focus goes to the
 * next one, then to the previous one, and only then back where it came from.
 * Done *before* the dismissal, because the node stays mounted for its exit — a
 * focus left on a card that is fading out is a focus nobody can see.
 */
function handOffFocus(params: Params, id: string | undefined): void {
  const { scope, refs, context } = params;
  const group = getGroupEl(scope);
  const active = scope.getActiveElement();
  const leaving = id === undefined ? group : getToastEl(scope, id);
  if (!contains(leaving, active)) return;

  const toasts = context.get("toasts");
  const index = id === undefined ? -1 : toasts.findIndex((record) => record.id === id);
  const target = index === -1 ? -1 : getRemovalIndex(index, { count: toasts.length });
  const next = target === -1 ? undefined : toasts[target];
  const node = next === undefined ? null : getToastEl(scope, next.id);
  if (node !== null) {
    focusElement(node);
    return;
  }
  const back = refs.get("returnFocusEl");
  if (back?.isConnected === true) focusElement(back);
}

function setInteractionPause(params: Params, paused: boolean): void {
  const toaster = params.prop("toaster");
  if (paused === params.context.get("pausedByInteraction")) return;
  params.context.set("pausedByInteraction", paused);
  if (paused) toaster.pause(INTERACTION);
  else toaster.resume(INTERACTION);
}

function pointerInside(params: Params): boolean {
  const group = getGroupEl(params.scope);
  return group?.matches(":hover") ?? false;
}

function focusInside(params: Params): boolean {
  return contains(getGroupEl(params.scope), params.scope.getActiveElement());
}

export const machine: Machine<ToastGroupSchema> = createMachine<ToastGroupSchema>({
  props({ props }) {
    const { toaster } = props;
    // Thrown rather than defaulted: there is no store to invent, and a region
    // rendered without one would sit there silently rendering nothing.
    invariant(
      toaster !== undefined,
      "a toast group needs a `toaster` — build one with `createToaster()`",
    );
    const resolved: ResolvedToastGroupMachineProps = {
      hotkey: DEFAULT_HOTKEY,
      pauseOnInteraction: true,
      pauseOnPageIdle: true,
      topLayer: true,
      intents: null,
      translations: {},
      ...props,
      toaster,
    };
    return resolved;
  },

  context({ prop, bindable }) {
    return {
      toasts: bindable<readonly ToastRecord[]>(() => ({
        defaultValue: prop("toaster").getVisibleToasts(),
        // Identity is not enough and deep equality is too much: what an adapter
        // has to re-render for is a toast arriving, leaving, starting its exit or
        // being updated — which is exactly the `(id, status, version)` sequence.
        isEqual: (a, b) =>
          a.length === b.length &&
          a.every((record, index) => {
            const other = b[index];
            return (
              other !== undefined &&
              record.id === other.id &&
              record.status === other.status &&
              record.version === other.version
            );
          }),
        debugLabel: "toast toasts",
      })),
      pausedByInteraction: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    visibleCount: ({ context }) => context.get("toasts").length,
    frontId: ({ context }) => context.get("toasts")[0]?.id ?? null,
  },

  refs() {
    return { returnFocusEl: null, announced: new Map<string, number>() };
  },

  // Pure: a store read, no document. The server renders the region it will hydrate.
  initialState({ prop }) {
    return prop("toaster").getVisibleToasts().length > 0 ? "active" : "empty";
  },

  effects: ["subscribeStore"],

  watch({ context, track, send }) {
    track(
      () => [context.get("toasts")],
      () => send({ type: "TOASTS.CHANGED" }),
    );
  },

  on: {
    "STORE.SYNC": { actions: ["syncToasts"] },
  },

  states: {
    empty: {
      on: {
        "TOASTS.CHANGED": { guard: "hasToasts", target: "active" },
      },
    },

    active: {
      effects: [
        "trackHotkey",
        "trackDocumentVisibility",
        "measureStack",
        "announceToasts",
        "captureIntents",
        "presentGroup",
        "trackGroupScrollEdges",
      ],
      on: {
        // The first branch is what keeps a non-empty change inside `active`; the
        // measurement is the observer's business, not a transition's.
        "TOASTS.CHANGED": [
          { guard: "hasToasts" },
          { target: "empty", actions: ["restoreFocusIfInside", "clearInteractionPause"] },
        ],
        "GROUP.POINTER_ENTER": { guard: "canPauseOnInteraction", actions: ["pauseForInteraction"] },
        "GROUP.POINTER_LEAVE": { guard: "canResumePointer", actions: ["resumeInteraction"] },
        "GROUP.FOCUS_ENTER": {
          actions: ["rememberReturnFocus", "pauseForInteractionIfEnabled"],
        },
        "GROUP.FOCUS_LEAVE": { actions: ["resumeInteractionIfEnabled", "forgetReturnFocus"] },
        "GROUP.HOTKEY": { actions: ["focusGroup"] },
        "TOAST.NAVIGATE": { actions: ["moveFocus"] },
        "TOAST.DISMISS": { actions: ["dismissToast"] },
        "TOAST.EXITED": { actions: ["removeToast"] },
        "DOC.VISIBILITY": [
          { guard: "isHiddenAndPausable", actions: ["pauseForPageIdle"] },
          { guard: "canResumePageIdle", actions: ["resumePageIdle"] },
        ],
      },
    },
  },

  implementations: {
    guards: {
      hasToasts: ({ context }) => context.get("toasts").length > 0,
      canPauseOnInteraction: ({ prop }) => prop("pauseOnInteraction"),
      // Both conditions have to fall away before the clock restarts: a pointer
      // leaving a region the keyboard is still inside has released nothing.
      canResumePointer: (params) =>
        params.context.get("pausedByInteraction") && !focusInside(params),
      isHiddenAndPausable: ({ prop, event }) =>
        event.type === "DOC.VISIBILITY" && event.hidden && prop("pauseOnPageIdle"),
      canResumePageIdle: ({ prop, event }) =>
        event.type === "DOC.VISIBILITY" && !event.hidden && prop("pauseOnPageIdle"),
    },

    actions: {
      syncToasts({ context, event }) {
        if (event.type === "STORE.SYNC") context.set("toasts", event.toasts);
      },

      pauseForInteraction: (params) => setInteractionPause(params, true),
      resumeInteraction: (params) => setInteractionPause(params, false),

      pauseForInteractionIfEnabled(params) {
        if (params.prop("pauseOnInteraction")) setInteractionPause(params, true);
      },

      resumeInteractionIfEnabled(params) {
        const { event, scope } = params;
        if (event.type !== "GROUP.FOCUS_LEAVE") return;
        // Moving between two toasts is not leaving, and a pointer still resting
        // on the region holds the clock on its own.
        if (contains(getGroupEl(scope), event.relatedTarget as Node | null)) return;
        if (pointerInside(params)) return;
        setInteractionPause(params, false);
      },

      clearInteractionPause: (params) => setInteractionPause(params, false),

      pauseForPageIdle({ prop }) {
        prop("toaster").pause(PAGE_IDLE);
      },

      resumePageIdle({ prop }) {
        prop("toaster").resume(PAGE_IDLE);
      },

      rememberReturnFocus({ refs, scope, event }) {
        if (event.type !== "GROUP.FOCUS_ENTER") return;
        const previous = event.relatedTarget;
        // Only the focus arriving from outside is worth remembering — moving
        // between two toasts must not overwrite where the person came from.
        if (contains(getGroupEl(scope), previous as Node | null)) return;
        // `isHTMLElement` rather than `instanceof`: the check has to survive an
        // iframe, where the constructor is a different realm's.
        refs.set("returnFocusEl", isHTMLElement(previous) ? previous : null);
      },

      forgetReturnFocus({ refs, scope, event }) {
        if (event.type !== "GROUP.FOCUS_LEAVE") return;
        if (contains(getGroupEl(scope), event.relatedTarget as Node | null)) return;
        refs.set("returnFocusEl", null);
      },

      focusGroup({ scope }) {
        focusElement(getGroupEl(scope));
      },

      moveFocus(params) {
        const { event, context, scope } = params;
        if (event.type !== "TOAST.NAVIGATE") return;
        const toasts = context.get("toasts");
        if (toasts.length === 0) return;
        // No loop: a stack has a front and a back, and wrapping from the last
        // card to the first would read as the list having moved under the focus.
        const next = getNextIndex(focusedIndex(params), event.to, {
          count: toasts.length,
          loop: false,
        });
        const record = toasts[next];
        if (record !== undefined) focusElement(getToastEl(scope, record.id));
      },

      dismissToast(params) {
        const { event, prop } = params;
        if (event.type !== "TOAST.DISMISS") return;
        handOffFocus(params, event.id);
        prop("toaster").dismiss(event.id, event.reason);
      },

      removeToast({ event, prop }) {
        if (event.type === "TOAST.EXITED") prop("toaster").remove(event.id);
      },

      restoreFocusIfInside({ refs, scope }) {
        const back = refs.get("returnFocusEl");
        refs.set("returnFocusEl", null);
        if (back === null || !back.isConnected) return;
        const active = scope.getActiveElement();
        // The last card has already left, so the focus is on `<body>` — or on
        // nothing at all, which is the same statement in a different browser.
        if (active !== null && active.tagName !== "BODY") return;
        focusElement(back);
      },
    },

    effects: {
      /**
       * Machine level, so the subscription outlives the empty ↔ active flip — and
       * it is this subscription that gates the store's clock: while no group is
       * mounted, no timer runs.
       */
      subscribeStore({ prop, send }) {
        const toaster = prop("toaster");
        send({ type: "STORE.SYNC", toasts: toaster.getVisibleToasts() });
        return toaster.subscribe((toasts) => send({ type: "STORE.SYNC", toasts }));
      },

      trackHotkey({ scope, prop, send }) {
        const group = getGroupEl(scope);
        if (group === null) return;
        // In capture, on the document, like every other global this library
        // installs: a page-level shortcut cannot depend on where the focus is.
        return addDomEvent(
          group.ownerDocument,
          "keydown",
          (event) => {
            if (!matchesHotkey(event, prop("hotkey"))) return;
            event.preventDefault();
            send({ type: "GROUP.HOTKEY" });
          },
          { capture: true },
        );
      },

      trackDocumentVisibility({ scope, send }) {
        const group = getGroupEl(scope);
        if (group === null) return;
        const doc = group.ownerDocument;
        return addDomEvent(doc, "visibilitychange", () => {
          send({ type: "DOC.VISIBILITY", hidden: doc.hidden });
        });
      },

      /**
       * The expanded position of every card, written **straight onto the node**:
       * it changes with every layout frame and no state depends on it, which is
       * the same trade `data-scroll` and `--sui-transform-origin` already make.
       *
       * The sheet cannot do this arithmetic itself. The cards are stacked in one
       * grid cell so that they can transform over each other, and a stacked card
       * has no idea how tall the ones in front of it are.
       */
      measureStack({ scope, prop }) {
        const group = getGroupEl(scope);
        const win = group?.ownerDocument.defaultView ?? null;
        if (group === null || win === null || !("ResizeObserver" in win)) return;
        // The core writes the offset already signed, so the sheet never has to
        // work out which way this placement grows.
        const direction = prop("toaster").placement.startsWith("bottom") ? -1 : 1;

        let observed: Element[] = [];

        const measure = (): void => {
          const style = win.getComputedStyle(group);
          const gap = Number.parseFloat(style.getPropertyValue("--sui-toast-gap"));
          const step = Number.isNaN(gap) ? DEFAULT_GAP : gap;
          let offset = 0;
          for (const node of getToastEls(scope)) {
            node.style.setProperty("--sui-toast-offset", `${offset * direction}px`);
            offset += node.offsetHeight + step;
          }
          // What the expanded stack occupies, so the region can cover it: a
          // hover that falls off the bottom of the region collapses the stack
          // out from under the pointer that was reaching for it.
          group.style.setProperty("--sui-toast-stack-size", `${Math.max(0, offset - step)}px`);
        };

        const observer = new win.ResizeObserver(() => measure());
        const sync = (): void => {
          for (const node of observed) observer.unobserve(node);
          observed = getToastEls(scope);
          for (const node of observed) observer.observe(node);
          measure();
        };

        sync();
        // A card added or removed changes every offset behind it, and a mutation
        // is the only signal for that — a `ResizeObserver` says nothing about a
        // node that has left.
        const stopChildren = observeChildren(group, sync);
        return () => {
          stopChildren();
          observer.disconnect();
        };
      },

      /**
       * One announcement per `(id, version)`. A re-render is not news, a promotion
       * out of the queue is — that is the moment a queued toast becomes something
       * a person can perceive, and the moment it is entitled to be read out.
       */
      announceToasts({ scope, prop, refs }) {
        const group = getGroupEl(scope);
        if (group === null) return;
        const announcer = getLiveAnnouncer(group.ownerDocument);
        const toaster = prop("toaster");

        const speak = (toasts: readonly ToastRecord[]): void => {
          const announced = refs.get("announced");
          const live = new Set<string>();
          for (const record of toasts) {
            live.add(record.id);
            if (record.status !== "visible") continue;
            if (announced.get(record.id) === record.version) continue;
            announced.set(record.id, record.version);
            const text =
              record.description === undefined
                ? record.title
                : `${record.title}. ${record.description}`;
            announcer.announce(text, record.politeness);
          }
          for (const id of [...announced.keys()]) {
            if (!live.has(id)) announced.delete(id);
          }
        };

        speak(toaster.getVisibleToasts());
        return toaster.subscribe(speak);
      },

      /**
       * Not trapped, and the handler answers only while the DOM focus is already
       * inside the region: B has to keep dismissing whatever is on the layer stack
       * as though the toasts were not there.
       */
      captureIntents(params) {
        const { prop, send, computed } = params;
        const host = prop("intents");
        if (host === null || host === undefined) return;
        return host.pushScope((event) => {
          if (!focusInside(params)) return false;
          switch (event.intent) {
            case "moveDown":
              send({ type: "TOAST.NAVIGATE", to: "next" });
              return true;
            case "moveUp":
              send({ type: "TOAST.NAVIGATE", to: "prev" });
              return true;
            case "home":
              send({ type: "TOAST.NAVIGATE", to: "first" });
              return true;
            case "end":
              send({ type: "TOAST.NAVIGATE", to: "last" });
              return true;
            case "back": {
              const id = focusedToast(params)?.id ?? computed("frontId") ?? undefined;
              if (id === undefined) return false;
              send({ type: "TOAST.DISMISS", id, reason: "back" });
              return true;
            }
            default:
              return false;
          }
        });
      },

      /**
       * The top layer, through the Popover API and with no light-dismiss: a modal
       * `<dialog>` anywhere on the page paints over any z-index, and a toast that
       * disappears behind one is a toast that did not happen. `manual` because
       * nothing here is dismissed by clicking elsewhere. Where the API is missing
       * the sheet's `--sui-z-toast` is the fallback, and it needs no code.
       */
      presentGroup({ scope, prop }) {
        const group = getGroupEl(scope);
        if (!prop("topLayer") || group === null || typeof group.showPopover !== "function") return;

        const lift = (): boolean => {
          try {
            group.showPopover();
            return true;
          } catch {
            return false;
          }
        };

        group.setAttribute("popover", "manual");
        if (!lift()) {
          // A region that cannot reach the top layer still renders: the sheet's
          // `--sui-z-toast` is the fallback, and it needs nothing from here.
          group.removeAttribute("popover");
          return;
        }

        /**
         * The top layer is a stack, not a plane: the last element to enter it
         * paints over everything already in it. Showing once was therefore only
         * half of what the comment above promises — a modal `<dialog>` opened
         * *after* the region covered the toasts, which is the exact case the
         * Popover API was reached for in the first place. Leaving and re-entering
         * is what moves an element back to the top.
         *
         * `showModal()` is observable because it writes `open` onto the dialog,
         * and nothing else has to be watched to catch it: a `<dialog open>`
         * rendered declaratively is *non-modal* and never reaches the top layer,
         * so there is no childList case and the observer stays an attribute
         * filter rather than a document-wide subtree scan.
         *
         * The one gap left, and it is named rather than papered over: another
         * `[popover]` shown after this one also lands above it, and a popover
         * entering the top layer changes no attribute and fires no event that
         * reaches this document. Consumers stacking a manual popover over a toast
         * region are on their own.
         */
        const doc = group.ownerDocument;
        const win = doc.defaultView;
        let observer: MutationObserver | null = null;
        if (win !== null) {
          observer = new win.MutationObserver((records) => {
            for (const record of records) {
              const target = record.target as Element;
              if (target.tagName !== "DIALOG" || !target.hasAttribute("open")) continue;
              try {
                group.hidePopover();
              } catch {
                // Already out of the top layer; re-entering is still the point.
              }
              if (!lift()) group.removeAttribute("popover");
              return;
            }
          });
          observer.observe(doc.documentElement, {
            subtree: true,
            attributes: true,
            attributeFilter: ["open"],
          });
        }

        return () => {
          observer?.disconnect();
          try {
            group.hidePopover();
          } catch {
            // Already hidden — the attribute below is still ours to take back.
          }
          group.removeAttribute("popover");
        };
      },

      trackGroupScrollEdges({ scope }) {
        return trackScrollEdges(getGroupEl(scope));
      },
    },
  },
});

/**
 * The queue, the ceiling and the clock — with no DOM in the room.
 *
 * `setTimeout` is the one global here and it is not a DOM access: it exists on a
 * server, it survives SSR, and nothing in this file reads a document. Everything
 * that touches one lives in the machine's effects, behind `scope`.
 *
 * **The clock is gated on the subscribers.** While nothing is mounted no timer
 * runs, because a toast that expired without ever being shown was never
 * perceived — a tab restored after ten minutes must not find its notifications
 * already gone.
 */

import type { Politeness } from "../../a11y/live-announcer";
import type {
  ToastDismissReason,
  Toaster,
  ToasterOptions,
  ToastOptions,
  ToastPromiseOptions,
  ToastRecord,
  ToastSubscriber,
  ToastType,
} from "./toast.types";

const DEFAULT_DURATION = 5000;
const DEFAULT_MAX = 3;

interface ToastHandlers {
  readonly onDismiss: ((details: { reason: ToastDismissReason }) => void) | undefined;
  readonly onRemove: (() => void) | undefined;
}

interface Timer {
  /** What is left to run. Frozen on pause, which is what makes a resume honest. */
  remaining: number;
  deadline: number;
  handle: ReturnType<typeof setTimeout> | null;
}

/**
 * `error` and `loading` are sticky by default, and that is the parity line with the
 * reference app, whose error strips stayed until someone dismissed them: a spinner that
 * disappears on a five second clock is a lie about the work still running.
 */
function defaultDuration(type: ToastType, fallback: number): number | null {
  return type === "error" || type === "loading" ? null : fallback;
}

function defaultPoliteness(type: ToastType): Politeness {
  return type === "error" ? "assertive" : "polite";
}

function resolveOptions<T>(
  source: ToastOptions | ((value: T) => ToastOptions),
  value: T,
): ToastOptions {
  return typeof source === "function" ? source(value) : source;
}

export function createToaster(options: ToasterOptions = {}): Toaster {
  const placement = options.placement ?? "top-end";
  const overlap = options.overlap ?? true;
  const max = Math.max(1, options.max ?? DEFAULT_MAX);
  const fallbackDuration = options.duration ?? DEFAULT_DURATION;

  let visible: readonly ToastRecord[] = [];
  let queued: readonly ToastRecord[] = [];
  let created = 0;
  let held = 0;

  const handlers = new Map<string, ToastHandlers>();
  const timers = new Map<string, Timer>();
  const holds = new Map<string, number>();
  const subscribers = new Set<ToastSubscriber>();

  function notify(): void {
    for (const subscriber of [...subscribers]) subscriber(visible);
  }

  function find(id: string): ToastRecord | undefined {
    return visible.find((record) => record.id === id) ?? queued.find((record) => record.id === id);
  }

  function stopTimer(id: string): void {
    const timer = timers.get(id);
    if (timer === undefined || timer.handle === null) return;
    clearTimeout(timer.handle);
    timer.handle = null;
    timer.remaining = Math.max(0, timer.deadline - Date.now());
  }

  function startTimer(id: string): void {
    if (subscribers.size === 0 || held > 0) return;
    const timer = timers.get(id);
    if (timer === undefined || timer.handle !== null) return;
    const record = visible.find((candidate) => candidate.id === id);
    if (record === undefined || record.status !== "visible") return;
    timer.deadline = Date.now() + timer.remaining;
    timer.handle = setTimeout(() => {
      timer.handle = null;
      dismissWith(id, "timeout");
    }, timer.remaining);
  }

  function armTimer(record: ToastRecord): void {
    timers.delete(record.id);
    if (record.duration === null) return;
    timers.set(record.id, { remaining: record.duration, deadline: 0, handle: null });
    startTimer(record.id);
  }

  function dropTimer(id: string): void {
    stopTimer(id);
    timers.delete(id);
  }

  /** A visible slot freed by a removal is filled by the oldest toast in the queue. */
  function promote(): void {
    while (visible.length < max && queued.length > 0) {
      const next = queued[0];
      if (next === undefined) return;
      queued = queued.slice(1);
      // In front: what was queued is newer than everything already on screen.
      visible = [next, ...visible];
      armTimer(next);
    }
  }

  function replace(record: ToastRecord): void {
    if (visible.some((candidate) => candidate.id === record.id)) {
      visible = visible.map((candidate) => (candidate.id === record.id ? record : candidate));
      return;
    }
    queued = queued.map((candidate) => (candidate.id === record.id ? record : candidate));
  }

  function dismissWith(id: string, reason: ToastDismissReason): void {
    const record = find(id);
    if (record === undefined || record.status === "dismissing") return;
    dropTimer(id);

    if (queued.some((candidate) => candidate.id === id)) {
      // Never mounted, so there is no exit to wait for and nothing to animate.
      queued = queued.filter((candidate) => candidate.id !== id);
      const entry = handlers.get(id);
      handlers.delete(id);
      entry?.onDismiss?.({ reason });
      entry?.onRemove?.();
      notify();
      return;
    }

    // Version untouched on purpose: a dismissal is not something to announce
    // again, and the announcer is keyed on `(id, version)`.
    replace({ ...record, status: "dismissing" });
    handlers.get(id)?.onDismiss?.({ reason });
    notify();
  }

  function removeOne(id: string): void {
    const wasVisible = visible.some((candidate) => candidate.id === id);
    if (!wasVisible && !queued.some((candidate) => candidate.id === id)) return;
    dropTimer(id);
    visible = visible.filter((candidate) => candidate.id !== id);
    queued = queued.filter((candidate) => candidate.id !== id);
    const entry = handlers.get(id);
    handlers.delete(id);
    entry?.onRemove?.();
    if (wasVisible) promote();
    notify();
  }

  function create(input: ToastOptions): string {
    created += 1;
    const id = input.id ?? `toast:${created}`;
    const type = input.type ?? "info";
    const record: ToastRecord = {
      id,
      type,
      title: input.title,
      description: input.description,
      duration:
        input.duration === undefined ? defaultDuration(type, fallbackDuration) : input.duration,
      closable: input.closable ?? true,
      action: input.action,
      politeness: input.politeness ?? defaultPoliteness(type),
      status: "visible",
      meta: input.meta,
      version: 0,
    };
    handlers.set(id, { onDismiss: input.onDismiss, onRemove: input.onRemove });

    if (visible.length < max) {
      visible = [record, ...visible];
      armTimer(record);
    } else {
      // Queued: not mounted, not announced, not on any clock. It becomes all
      // three at once, when a slot frees up and `promote` puts it on screen.
      queued = [...queued, record];
    }
    notify();
    return id;
  }

  function update(id: string, changes: Partial<Omit<ToastOptions, "id">>): void {
    const record = find(id);
    if (record === undefined) return;
    const type = changes.type ?? record.type;
    const duration =
      changes.duration !== undefined
        ? changes.duration
        : type === record.type
          ? record.duration
          : defaultDuration(type, fallbackDuration);

    const next: ToastRecord = {
      ...record,
      type,
      title: changes.title ?? record.title,
      description: "description" in changes ? changes.description : record.description,
      duration,
      closable: changes.closable ?? record.closable,
      action: "action" in changes ? changes.action : record.action,
      politeness:
        changes.politeness ??
        (changes.type === undefined ? record.politeness : defaultPoliteness(type)),
      meta: "meta" in changes ? changes.meta : record.meta,
      // The announcer speaks again: loading → success is new information, and
      // the live region deduplicates identical text on its own.
      version: record.version + 1,
    };

    if ("onDismiss" in changes || "onRemove" in changes) {
      const entry = handlers.get(id);
      handlers.set(id, {
        onDismiss: "onDismiss" in changes ? changes.onDismiss : entry?.onDismiss,
        onRemove: "onRemove" in changes ? changes.onRemove : entry?.onRemove,
      });
    }

    replace(next);
    if (next.status === "visible") armTimer(next);
    notify();
  }

  const toaster: Toaster = {
    create,
    update,
    placement,
    overlap,

    dismiss(id?: string | undefined, reason: ToastDismissReason = "programmatic"): void {
      if (id !== undefined) {
        dismissWith(id, reason);
        return;
      }
      for (const record of [...visible, ...queued]) dismissWith(record.id, reason);
    },

    remove(id?: string | undefined): void {
      if (id !== undefined) {
        removeOne(id);
        return;
      }
      for (const record of [...visible, ...queued]) removeOne(record.id);
    },

    pause(reason = "manual"): void {
      holds.set(reason, (holds.get(reason) ?? 0) + 1);
      held += 1;
      if (held !== 1) return;
      for (const id of timers.keys()) stopTimer(id);
    },

    resume(reason = "manual"): void {
      const count = holds.get(reason) ?? 0;
      if (count === 0) return;
      if (count === 1) holds.delete(reason);
      else holds.set(reason, count - 1);
      held -= 1;
      if (held !== 0) return;
      for (const id of timers.keys()) startTimer(id);
    },

    promise<T>(promise: Promise<T>, promiseOptions: ToastPromiseOptions<T>): Promise<T> {
      const id = create({ type: "loading", ...promiseOptions.loading });
      return promise.then(
        (value) => {
          update(id, { type: "success", ...resolveOptions(promiseOptions.success, value) });
          return value;
        },
        (error: unknown) => {
          update(id, { type: "error", ...resolveOptions(promiseOptions.error, error) });
          throw error;
        },
      );
    },

    isVisible: (id: string): boolean => visible.some((record) => record.id === id),
    getVisibleToasts: (): readonly ToastRecord[] => visible,
    getQueuedCount: (): number => queued.length,

    subscribe(callback: ToastSubscriber): () => void {
      subscribers.add(callback);
      if (subscribers.size === 1) {
        for (const id of timers.keys()) startTimer(id);
      }
      return () => {
        if (!subscribers.delete(callback)) return;
        if (subscribers.size > 0) return;
        for (const id of timers.keys()) stopTimer(id);
      };
    },
  };

  return toaster;
}

/**
 * Two objects, one machine.
 *
 * `Toaster` is a pure store — a queue, a ceiling, timers and statuses, with no
 * DOM and no framework anywhere near it. It is created imperatively, which is the
 * whole point: an error strip spawned from an event handler in a module that is
 * not a component has nowhere to hang a hook.
 *
 * The machine below it is the bridge to the page: it subscribes to the store,
 * posts the ARIA, pauses on hover and focus, answers the hotkey, measures the
 * stack and hands the focus over when a toast the person is standing on leaves.
 * **An individual toast has no machine of its own** — it is a store record plus a
 * presence in the adapter, because the runtime spawns no dynamic actors.
 */

import type { Politeness } from "../../a11y/live-announcer";
import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction } from "../../types";

export type ToastType = "info" | "success" | "warning" | "error" | "loading";

export type ToastPlacement =
  | "top"
  | "top-start"
  | "top-end"
  | "bottom"
  | "bottom-start"
  | "bottom-end";

/** `dismissing` is on screen and on its way out — the adapter's presence owns the exit. */
export type ToastStatus = "visible" | "dismissing";

export type ToastDismissReason =
  | "timeout"
  | "close-trigger"
  | "escape"
  | "back"
  | "programmatic"
  | "action";

export interface ToastDismissDetails {
  readonly reason: ToastDismissReason;
}

export interface ToastActionOptions {
  readonly label: string;
  onClick(): void;
  /** Default `true`: activating the action closes the toast, with reason `"action"`. */
  readonly dismissOnClick?: boolean | undefined;
}

export interface ToastOptions {
  /** Defaults to a counter-derived `"toast:n"` — never random, so a server render matches. */
  readonly id?: string | undefined;
  readonly type?: ToastType | undefined;
  /** Required: this is what the announcer says. */
  readonly title: string;
  readonly description?: string | undefined;
  /** ms, or `null` for sticky. Defaults to the toaster's, except `error`/`loading` → `null`. */
  readonly duration?: number | null | undefined;
  readonly closable?: boolean | undefined;
  readonly action?: ToastActionOptions | undefined;
  /** Overrides the politeness derived from the type (`error` speaks assertively). */
  readonly politeness?: Politeness | undefined;
  readonly onDismiss?: ((details: ToastDismissDetails) => void) | undefined;
  readonly onRemove?: (() => void) | undefined;
  /** Opaque to the library, carried through to the app's own rendering. */
  readonly meta?: Record<string, unknown> | undefined;
}

export interface ToastRecord {
  readonly id: string;
  readonly type: ToastType;
  readonly title: string;
  readonly description: string | undefined;
  readonly duration: number | null;
  readonly closable: boolean;
  readonly action: ToastActionOptions | undefined;
  readonly politeness: Politeness;
  readonly status: ToastStatus;
  readonly meta: Record<string, unknown> | undefined;
  /**
   * Bumped on every mutation of the record, and it is load-bearing twice over: it
   * is what the context's `isEqual` compares, and it is what stops the announcer
   * from repeating a toast that merely re-rendered.
   */
  readonly version: number;
}

export interface ToasterOptions {
  /** Default `"top-end"` — the native desktop notification corner. Touch apps pass `"top"`. */
  readonly placement?: ToastPlacement | undefined;
  /** Ceiling on *visible* toasts; the rest queue. Default 3 (the iOS stack shows 1 + 2). */
  readonly max?: number | undefined;
  readonly duration?: number | undefined;
  /** Default `true` — the stack. `false` lays the toasts out as a spaced list. */
  readonly overlap?: boolean | undefined;
}

export interface ToastPromiseOptions<T> {
  readonly loading: ToastOptions;
  readonly success: ToastOptions | ((value: T) => ToastOptions);
  readonly error: ToastOptions | ((error: unknown) => ToastOptions);
}

export type ToastSubscriber = (toasts: readonly ToastRecord[]) => void;

export interface Toaster {
  create(options: ToastOptions): string;
  update(id: string, options: Partial<Omit<ToastOptions, "id">>): void;
  /**
   * Without an id: every toast, visible and queued alike. `reason` is not in the
   * spec's signature and has to be — it is the only way `onDismiss` can tell an
   * Escape from a timeout, and the machine has that answer at the call site.
   */
  dismiss(id?: string | undefined, reason?: ToastDismissReason | undefined): void;
  /** Skips the exit animation entirely. Without an id: all of them. */
  remove(id?: string | undefined): void;
  /** Reason-counted, so hover and a hidden page cannot release each other's hold. */
  pause(reason?: string | undefined): void;
  resume(reason?: string | undefined): void;
  promise<T>(promise: Promise<T>, options: ToastPromiseOptions<T>): Promise<T>;
  /** Mounted — a toast still playing its exit is one of these. */
  isVisible(id: string): boolean;
  /** Index 0 is the most recent, which is the front of the stack. */
  getVisibleToasts(): readonly ToastRecord[];
  getQueuedCount(): number;
  readonly placement: ToastPlacement;
  readonly overlap: boolean;
  /**
   * Also the clock's gate: with no subscriber nothing is mounted, and a toast that
   * expires without ever having been shown was never perceived.
   */
  subscribe(callback: ToastSubscriber): () => void;
}

/**
 * Both halves stay optional through the resolution — the machine's props type is
 * the *input* type as well as the output one, so promoting them to required here
 * would make an adapter that passes one of the two fail to typecheck. The
 * fallbacks live in `connect`, which is pure and where the count is anyway.
 */
export interface ToastTranslations {
  regionLabel?: ((count: number) => string) | undefined;
  dismissLabel?: string | undefined;
}

export interface ToastGroupMachineProps {
  /** Required — the store this region renders. No default: there is nothing to invent. */
  readonly toaster: Toaster;
  /**
   * Every entry must match: modifier flags by name (`"altKey"`…), everything else
   * against `event.code` then `event.key`. Default `["F6"]`, the APG's own key for
   * moving to a notification region.
   */
  readonly hotkey?: readonly string[] | undefined;
  readonly pauseOnInteraction?: boolean | undefined;
  readonly pauseOnPageIdle?: boolean | undefined;
  /**
   * Default `true`: the region asks the Popover API for the top layer, which is
   * the only way to sit above a modal `<dialog>`. `false` is for a region an app
   * lays out itself — docked in a panel, or four of them in a documentation
   * matrix — where being lifted out of the page is exactly wrong.
   */
  readonly topLayer?: boolean | undefined;
  readonly translations?: ToastTranslations | undefined;
  readonly dir?: Direction | undefined;
  /** Where the gamepad scope is pushed; the adapter hands its `InputSystem` in. */
  readonly intents?: IntentScopeHost | null | undefined;
}

export interface ResolvedToastGroupMachineProps extends ToastGroupMachineProps {
  readonly hotkey: readonly string[];
  readonly pauseOnInteraction: boolean;
  readonly pauseOnPageIdle: boolean;
  readonly topLayer: boolean;
  readonly translations: ToastTranslations;
  readonly intents: IntentScopeHost | null;
}

export interface ToastGroupSchema extends MachineSchema {
  state: "empty" | "active";
  props: ResolvedToastGroupMachineProps;
  context: {
    /**
     * The store's mirror. `isEqual` is not optional here: without it every
     * notification — a pause, a queued create nobody can see — would re-render
     * every adapter that has a toast on screen.
     */
    toasts: readonly ToastRecord[];
    pausedByInteraction: boolean;
  };
  computed: { visibleCount: number; frontId: string | null };
  refs: {
    /** Who had the focus before it entered the region. */
    returnFocusEl: HTMLElement | null;
    /** The last version announced per id — a re-render is not a new announcement. */
    announced: Map<string, number>;
  };
  event:
    | { type: "STORE.SYNC"; toasts: readonly ToastRecord[] }
    | { type: "TOASTS.CHANGED" }
    | { type: "GROUP.POINTER_ENTER" }
    | { type: "GROUP.POINTER_LEAVE" }
    | { type: "GROUP.FOCUS_ENTER"; relatedTarget: EventTarget | null }
    | { type: "GROUP.FOCUS_LEAVE"; relatedTarget: EventTarget | null }
    | { type: "GROUP.HOTKEY" }
    | { type: "TOAST.NAVIGATE"; to: RovingAction }
    | { type: "TOAST.DISMISS"; id: string | undefined; reason: ToastDismissReason }
    | { type: "TOAST.EXITED"; id: string }
    | { type: "DOC.VISIBILITY"; hidden: boolean };
  action:
    | "syncToasts"
    | "pauseForInteraction"
    | "pauseForInteractionIfEnabled"
    | "resumeInteraction"
    | "resumeInteractionIfEnabled"
    | "pauseForPageIdle"
    | "resumePageIdle"
    | "rememberReturnFocus"
    | "forgetReturnFocus"
    | "focusGroup"
    | "moveFocus"
    | "dismissToast"
    | "removeToast"
    | "restoreFocusIfInside"
    | "clearInteractionPause";
  guard:
    | "hasToasts"
    | "canPauseOnInteraction"
    | "canResumePointer"
    | "isHiddenAndPausable"
    | "canResumePageIdle";
  effect:
    | "subscribeStore"
    | "trackHotkey"
    | "trackDocumentVisibility"
    | "measureStack"
    | "announceToasts"
    | "captureIntents"
    | "presentGroup"
    | "trackGroupScrollEdges";
}

export interface ToastApi<T extends PropTypes = PropTypes> {
  readonly toasts: readonly ToastRecord[];
  readonly count: number;
  readonly queuedCount: number;
  readonly paused: boolean;
  /** The one focus move the library initiates, and it answers a key the user pressed. */
  focusGroup(): void;
  dismiss(id?: string | undefined): void;
  /** The adapter's presence, reporting that a toast has finished leaving. */
  notifyExit(id: string): void;
  getGroupProps(): T["element"];
  getRootProps(toast: ToastRecord): T["element"];
  getIndicatorProps(toast: ToastRecord): T["element"];
  getTitleProps(toast: ToastRecord): T["element"];
  getDescriptionProps(toast: ToastRecord): T["element"];
  getActionTriggerProps(toast: ToastRecord): T["button"];
  getCloseTriggerProps(toast: ToastRecord): T["button"];
}

/**
 * `<Toast toaster={t}/>` — the region, and a card for every record in it.
 *
 * **The bare name is the GROUP, not the card**, which is the arbitration this file
 * carries. Seven parts in the anatomy, and `root` is the card rather than the
 * region — the region is `group`. A composed card would have been the first layer
 * in the library whose outermost node is not its own component's root, its parity
 * row would have had to wrap a `<ToastGroup>` the layer does not own, and it would
 * not have removed the passage this layer exists to remove: `children` is a
 * REQUIRED render-prop on the group, so a consumer composing cards would still
 * write the region, the store read and the map by hand.
 *
 * **The default body is only possible because the sheet draws the five severity
 * marks.** A record carries a `type` and no icon — `ToastOptions` has no such
 * field — so a default card can derive its mark from the severity and nothing
 * else. `_toast.scss` now draws info, success, warning, error and the spinner under
 * `:empty`, which is what took this folder off the pending list the V4 wave put it
 * on. A consumer who hands their own symbol through `parts.indicator` stops the
 * `:empty` matching and pays nothing for the defaults.
 *
 * **Both names come through `translations`**, which is a machine prop and travels
 * untouched: `regionLabel` names the landmark and `dismissLabel` the close button,
 * and the machine defaults both — so this layer invents no English of its own and
 * takes no label prop.
 *
 * `renderCard(record, defaults)` is the escape hatch the closed vocabulary allows:
 * it is handed the record and the card this layer would have rendered, so a
 * consumer can wrap it, replace one branch, or ignore it.
 */

import type * as toast from "@standarui/core/toast";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  ToastActionTrigger,
  ToastCloseTrigger,
  ToastDescription,
  ToastGroup,
  type ToastGroupProps,
  ToastIndicator,
  ToastRoot,
  ToastTitle,
} from "./toast";

/** Applied last on every part, so the consumer's entry wins over the placement. */
export interface ToastParts {
  readonly root?: Omit<PartProps<"div">, "toast"> | undefined;
  /**
   * The severity mark. Hand it a child and the sheet's own drawing steps aside —
   * `:empty` is the whole guard — which is how a consumer keeps their icon set.
   */
  readonly indicator?: PartProps<"span"> | undefined;
  readonly title?: PartProps<"div"> | undefined;
  readonly description?: PartProps<"div"> | undefined;
  readonly actionTrigger?: PartProps<"button"> | undefined;
  readonly closeTrigger?: PartProps<"button"> | undefined;
}

export interface ToastComposedProps
  extends Omit<ToastGroupProps, "children" | "render" | "asChild"> {
  /**
   * Handed each record and the card this layer would have rendered for it. Return
   * the card to keep it, wrap it, or ignore it and build your own.
   */
  readonly renderCard?: ((record: toast.ToastRecord, defaults: ReactNode) => ReactNode) | undefined;
  readonly parts?: ToastParts | undefined;
}

export function Toast(props: ToastComposedProps): ReactNode {
  const { renderCard, parts, ...group } = props;

  return (
    <ToastGroup {...group}>
      {(record) => {
        const card = (
          <ToastRoot toast={record} {...parts?.root}>
            {record.type === undefined ? null : <ToastIndicator {...parts?.indicator} />}
            <ToastTitle {...parts?.title}>{record.title}</ToastTitle>
            {record.description === undefined ? null : (
              <ToastDescription {...parts?.description}>{record.description}</ToastDescription>
            )}
            {record.action === undefined ? null : (
              <ToastActionTrigger {...parts?.actionTrigger}>
                {record.action.label}
              </ToastActionTrigger>
            )}
            {record.closable === true ? <ToastCloseTrigger {...parts?.closeTrigger} /> : null}
          </ToastRoot>
        );

        return renderCard === undefined ? card : renderCard(record, card);
      }}
    </ToastGroup>
  );
}

/**
 * The toast in React: one machine for the region, one presence per card, and a
 * render prop in between.
 *
 * The render prop is not a stylistic choice. A toast is created at runtime from a
 * store the app owns — often from a module that is not a component at all — so
 * there is no JSX the library could have written for it: the app is handed each
 * record and renders the card it wants, `meta` included. What the library keeps
 * is the region, the ARIA, the keyboard, the hand-off and the exit.
 *
 * `createToaster` is re-exported rather than wrapped, because it is UI-less: the
 * same call works in a React tree, in a worker-adjacent module, or in the error
 * handler of a fetch that no component is watching.
 */

import type { Service } from "@standarui/core";
import * as toast from "@standarui/core/toast";
import { type ReactNode, type Ref, useEffect, useMemo, useRef } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { usePresence } from "../../presence";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type {
  ToastActionOptions,
  ToastDismissDetails,
  ToastDismissReason,
  Toaster,
  ToasterOptions,
  ToastOptions,
  ToastPlacement,
  ToastPromiseOptions,
  ToastRecord,
  ToastStatus,
  ToastType,
} from "@standarui/core/toast";
export { createToaster } from "@standarui/core/toast";

export type ToastApi = toast.ToastApi<ReactPropTypes>;

export interface UseToastGroupProps extends toast.ToastGroupMachineProps, MachineRuntimeProps {}

interface ToastContextValue {
  readonly api: ToastApi;
  /** `none` is the only motion mode with nothing to wait for (see `dialog`). */
  readonly immediate: boolean;
}

interface ToastItemContextValue {
  readonly api: ToastApi;
  readonly toast: toast.ToastRecord;
}

const ToastContext = createPartContext<ToastContextValue>("ToastGroup");
const ToastItemContext = createPartContext<ToastItemContextValue>("ToastRoot");

function useToastService(props: UseToastGroupProps): Service<toast.ToastGroupSchema> {
  const host = useIntentScopeHost();
  return useMachine(toast.machine, {
    ...props,
    // `??` would override an explicit `null`, which is how a consumer says "this
    // region answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
  });
}

export function useToastGroup(props: UseToastGroupProps): ToastApi {
  return toast.connect(useToastService(props), normalizeProps);
}

/** The region's api, for a card rendered outside the render prop's own subtree. */
export function useToastGroupContext(): ToastApi {
  return ToastContext.usePart("ToastGroupContext").api;
}

/** The record this card is rendering — what a custom part reads instead of a prop. */
export function useToastContext(): toast.ToastRecord {
  return ToastItemContext.usePart("ToastContext").toast;
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "toaster",
  "hotkey",
  "pauseOnInteraction",
  "pauseOnPageIdle",
  "topLayer",
  "translations",
  "intents",
] as const;

export interface ToastGroupProps
  extends UseToastGroupProps,
    Omit<PartProps<"div", UseToastGroupProps>, "children">,
    Omit<PortalProps, "children" | "disabled"> {
  /** Renders the region where it was written instead of on the body. */
  readonly portalled?: boolean | undefined;
  /** Handed every visible record, front first. */
  readonly children: (record: toast.ToastRecord) => ReactNode;
}

export function ToastGroup(props: ToastGroupProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { children, container, portalled, render, asChild, ...elementProps } = rest;
  const api = toast.connect(useToastService(machineProps), normalizeProps);
  const { motion } = useEnvironment();

  const value: ToastContextValue = { api, immediate: motion === "none" };

  const cards = api.toasts.map((record) => (
    <ToastItemContext.Provider key={record.id} value={{ api, toast: record }}>
      {children(record)}
    </ToastItemContext.Provider>
  ));

  // Always rendered, empty or not: the region is a landmark, and one that comes
  // and goes with the first notification is one a screen reader has to discover
  // twice. It also guarantees the machine's effects find their node the moment
  // the first toast arrives, rather than a commit later.
  return (
    <ToastContext.Provider value={value}>
      <Portal container={container} disabled={portalled === false}>
        {useRender({
          render,
          asChild,
          element: "div",
          props: api.getGroupProps(),
          elementProps,
          children: cards,
        })}
      </Portal>
    </ToastContext.Provider>
  );
}

export interface ToastRootProps extends PartProps<"div"> {
  readonly toast: toast.ToastRecord;
}

/**
 * One presence per card, on the dialog's model: `dismissing` writes
 * `data-state="closed"`, the sheet's exit transition runs, and only when it has
 * finished does the record leave the store. Without the wait the node would be
 * gone on the same tick and nobody would ever see a toast leave.
 */
export function ToastRoot(props: ToastRootProps): ReactNode {
  const { toast: record, render, asChild, children, ref, ...elementProps } = props;
  const context = ToastContext.usePart("ToastRoot");
  const { api, immediate } = context;

  const leaving = record.status !== "visible";
  const presence = usePresence({ present: !leaving, immediate });
  const composed = useMemo(
    (): Ref<HTMLElement> => composeRefs(presence.ref, ref),
    [presence.ref, ref],
  );

  // No dependency array, and a latch instead: `api` is a fresh object every
  // render (that is what `connect` is), so a dependency on it would re-run this
  // on every commit — and reporting the same exit twice would remove a record
  // somebody has since re-created under the same id.
  const reported = useRef(false);
  useEffect(() => {
    if (!leaving || presence.present) {
      reported.current = false;
      return;
    }
    if (reported.current) return;
    reported.current = true;
    api.notifyExit(record.id);
  });

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: api.getRootProps(record),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  return presence.present || !leaving ? element : null;
}

export const ToastIndicator: (props: PartProps<"span">) => ReactNode = createPart(
  ToastItemContext,
  {
    name: "ToastIndicator",
    element: "span",
    props: (context) => context.api.getIndicatorProps(context.toast),
  },
);

export const ToastTitle: (props: PartProps<"div">) => ReactNode = createPart(ToastItemContext, {
  name: "ToastTitle",
  element: "div",
  props: (context) => context.api.getTitleProps(context.toast),
});

